"""Replay actual saved bone animation at all sparse ticks, without changing images."""
import bpy,json,hashlib,math
from pathlib import Path
from mathutils import Vector
P=Path(__file__).resolve().parent;s=json.loads((P/'source/source.json').read_text());blend=P/'source/authoring-rig.blend';bpy.ops.wm.open_mainfile(filepath=str(blend));rig=bpy.data.objects['OriginalTargetPickup'];rows=[]
for f in s['frames']:
    t=f['rig_frame'];bpy.context.scene.frame_set(math.floor(t),subframe=t-math.floor(t));bpy.context.view_layer.update();errors=[]
    for name,a,b,parent in s['bone_definitions']:
        p=rig.pose.bones[name];start=Vector(f['points'][a]['world_xyz']);end=Vector(f['points'][b]['world_xyz']) if b else start+Vector((0,0,.06));errors.extend([(p.head-start).length,(p.tail-end).length])
    rows.append(dict(index=f['index'],rig_frame=t,maximum_endpoint_error=max(errors)))
r=dict(blend_sha256=hashlib.sha256(blend.read_bytes()).hexdigest(),scene_fps=bpy.context.scene.render.fps,actual_rig_duration_seconds=(s['frames'][-1]['rig_frame']-s['frames'][0]['rig_frame'])/bpy.context.scene.render.fps,frames=rows,pass_=max(r['maximum_endpoint_error'] for r in rows)<1e-5,scope='Animated bones replay only; mesh capture states are regenerated by renderer script, not a final skinned game model.')
(P/'source-bone-replay.json').write_text(json.dumps(r,indent=2)+'\n');print('BONE_REPLAY',r['pass_']);assert r['pass_']
